import{_ as e,a0 as o,w as d,s as r,ao as l,I as p,x as a,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Arch Linux 中启用 Snap 支持 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Arch Linux 中启用 Snap 支持 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Arch Linux 中启用 Snap 支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Arch Linux 中启用 Snap 支持 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221011 How to Enable Snap Support in Arch Linux","title":"如何在 Arch Linux 中启用 Snap 支持","tag":"202210","desc":""},"relativePath":"202210/20221011 How to Enable Snap Support in Arch Linux.md","filePath":"[post].md"}'),u={name:"202210/20221011 How to Enable Snap Support in Arch Linux.md"};function h(g,s,k,f,m,b){const n=o("Link");return d(),r("div",null,[s[32]||(s[32]=l('<h1 id="如何在-arch-linux-中启用-snap-支持" tabindex="-1">如何在 Arch Linux 中启用 Snap 支持 <a class="header-anchor" href="#如何在-arch-linux-中启用-snap-支持" aria-label="Permalink to “如何在 Arch Linux 中启用 Snap 支持”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/21/100128gzzqkf3fcg3f6q3n.jpg" alt=""></p><p>Snap 是由 Ubuntu 的母公司 Canonical 设计的通用包格式。有些人不喜欢 Snap，但它有一些优势。</p><p>通常，某些应用仅以 Snap 格式提供。这为你提供了在 Arch Linux 中启用 Snap 的充分理由。</p><p>我知道 AUR 拥有大量应用，但 Snap 应用通常直接来自开发人员。</p><p>如果你希望能够在 Arch Linux 中安装 Snap 应用，你需要先启用 Snap 支持。</p><p>有两种方法可以做到：</p><ul><li>使用 AUR 助手启用 Snap 支持（更简单）</li><li>通过从 AUR 获取包，手动启用 Snap 支持</li></ul><p>让我们看看怎么做。</p><h3 id="方法-1、使用-aur-助手启用-snap" tabindex="-1">方法 1、使用 AUR 助手启用 Snap <a class="header-anchor" href="#方法-1、使用-aur-助手启用-snap" aria-label="Permalink to “方法 1、使用 AUR 助手启用 Snap”">​</a></h3><p>Snap 支持在 Arch 用户仓库中以 <code>snapd</code> 包的形式提供。你可以使用 AUR 助手轻松安装它。</p>',11)),p("p",null,[s[2]||(s[2]=a("有 ",-1)),t(n,{href:"https://itsfoss.com/best-aur-helpers/"},{default:i(()=>[...s[0]||(s[0]=[a("许多 AUR 助手",-1)])]),_:1}),s[3]||(s[3]=a("，但 ",-1)),s[4]||(s[4]=p("code",null,"yay",-1)),s[5]||(s[5]=a(" 是我更喜欢的，因为它的语法类似于 ",-1)),t(n,{href:"https://itsfoss.com/pacman-command/"},{default:i(()=>[...s[1]||(s[1]=[a("pacman 命令",-1)])]),_:1}),s[6]||(s[6]=a("。",-1))]),s[33]||(s[33]=l(`<p>如果你还没有安装 AUR，请使用以下命令安装 Yay（需要事先安装 <code>git</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://aur.archlinux.org/yay</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd yay</span></span>
<span class="line"><span></span></span>
<span class="line"><span>makepkg -si</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/yay-makepkg.png" alt="安装 yay"></p><p>现在 <code>yay</code> 已安装，你可以通过以下方式安装 <code>snapd</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>yay -Sy snapd</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/yay-install-snapd.png" alt="使用 yay 从 AUR 安装 snapd"></p>`,6)),p("p",null,[s[8]||(s[8]=a("每当你 ",-1)),t(n,{href:"https://itsfoss.com/update-arch-linux/"},{default:i(()=>[...s[7]||(s[7]=[a("更新 Arch Linux",-1)])]),_:1}),s[9]||(s[9]=a(" 系统时，",-1)),s[10]||(s[10]=p("code",null,"yay",-1)),s[11]||(s[11]=a(" 都会启用 ",-1)),s[12]||(s[12]=p("code",null,"snapd",-1)),s[13]||(s[13]=a(" 的自动更新。",-1))]),s[34]||(s[34]=l(`<h4 id="验证-snap-支持是否有效" tabindex="-1">验证 Snap 支持是否有效 <a class="header-anchor" href="#验证-snap-支持是否有效" aria-label="Permalink to “验证 Snap 支持是否有效”">​</a></h4><p>要测试 Snap 支持是否正常工作，请安装并运行 <code>hello-world</code> Snap 包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install hello-world</span></span>
<span class="line"><span></span></span>
<span class="line"><span>hello-world</span></span>
<span class="line"><span>（或者）</span></span>
<span class="line"><span>sudo snap run hello-world</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snap-hello-world-1.png" alt="hello-world Snap 包执行"></p><p>如果它运行良好，那么你可以轻松安装其他 Snap 包。</p><h3 id="方法-2、从-aur-手动构建-snapd-包" tabindex="-1">方法 2、从 AUR 手动构建 snapd 包 <a class="header-anchor" href="#方法-2、从-aur-手动构建-snapd-包" aria-label="Permalink to “方法 2、从 AUR 手动构建 snapd 包”">​</a></h3><p>如果你不想使用 AUR 助手，你仍然可以从 AUR 获取 <code>snapd</code>。让我展示详细的过程。</p><p>你需要先安装一些构建工具。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -Sy git go go-tools python-docutils</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-dependencies.png" alt="为 Snap 安装依赖项"></p><p>完成依赖项安装后，现在可以克隆 <code>snapd</code> 的 AUR 目录，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://aur.archlinux.org/snapd</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cd snapd</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-clone.png" alt="克隆仓库"></p><p>然后构建 <code>snapd</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>makepkg -si</span></span></code></pre></div><p>当它要求安装其他依赖包时输入 <code>yes</code>。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/snapd-manual-install-makepkg-800x460.png" alt="手动构建 snapd"></p><p>你已安装 <code>snapd</code> 守护程序。但是，需要启用它以在启动时自动启动。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl enable snapd --now</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo systemctl enable snapd.apparmor --now #start snap applications</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo ln -s /var/lib/snapd/snap /snap #optional: classic snap support</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/10/enable-snapd-startup-2.png" alt="启动时启用 Snap"></p><p>手动构建包的主要缺点是每次新更新启动时你都必须手动构建。使用 AUR 助手为我们解决了这个问题。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3>`,22)),p("p",null,[s[15]||(s[15]=a("我更喜欢 Arch Linux 中的 pacman 和 AUR。很少能看到不在 AUR 中但以其他格式提供的应用。尽管如此，在某些你希望直接从源获取它的情况下，使用 Snap 可能是有利的，例如 ",-1)),t(n,{href:"https://itsfoss.com/install-spotify-arch/"},{default:i(()=>[...s[14]||(s[14]=[a("在 Arch 上安装 Spotify",-1)])]),_:1}),s[16]||(s[16]=a("。",-1))]),s[35]||(s[35]=p("p",null,"希望本教程对你有所帮助。如果你有任何问题，请告诉我。",-1)),s[36]||(s[36]=p("hr",null,null,-1)),p("p",null,[s[18]||(s[18]=a("via: ",-1)),t(n,{href:"https://itsfoss.com/install-snap-arch-linux/"},{default:i(()=>[...s[17]||(s[17]=[a("https://itsfoss.com/install-snap-arch-linux/",-1)])]),_:1})]),p("p",null,[s[23]||(s[23]=a("作者：",-1)),t(n,{href:"https://itsfoss.com/author/pranav/"},{default:i(()=>[...s[19]||(s[19]=[a("Pranav Krishna",-1)])]),_:1}),s[24]||(s[24]=a(" 选题：",-1)),t(n,{href:"https://github.com/lkxed"},{default:i(()=>[...s[20]||(s[20]=[a("lkxed",-1)])]),_:1}),s[25]||(s[25]=a(" 译者：",-1)),t(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[21]||(s[21]=[a("geekpi",-1)])]),_:1}),s[26]||(s[26]=a(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[22]||(s[22]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[29]||(s[29]=a("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[27]||(s[27]=[a("LCTT",-1)])]),_:1}),s[30]||(s[30]=a(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:i(()=>[...s[28]||(s[28]=[a("Linux中国",-1)])]),_:1}),s[31]||(s[31]=a(" 荣誉推出",-1))])])}const S=e(u,[["render",h]]);export{x as __pageData,S as default};
